package app.flowdrop.mobile.test;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.MediaStore;import app.flowdrop.mobile.*;import java.io.*;import java.util.*;import java.util.zip.*;import java.util.concurrent.atomic.AtomicReference;import org.json.*;
public final class NativeFolderSmoke extends Instrumentation {
 interface Condition{boolean test()throws Exception;}
 void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 void await(Condition test,String message)throws Exception{long end=SystemClock.elapsedRealtime()+150000;while(SystemClock.elapsedRealtime()<end){if(test.test())return;SystemClock.sleep(200);}throw new AssertionError(message);}
 void stage(String text){Bundle b=new Bundle();b.putString("stage",text);sendStatus(1,b);}
 @Override public void onCreate(Bundle args){super.onCreate(args);start();}
 JSONObject history(Context c,String code)throws Exception{JSONArray list=TransferHistory.read(c);for(int i=0;i<list.length();i++){JSONObject item=list.getJSONObject(i);if("receive".equals(item.optString("direction"))&&code.equals(item.optString("code")))return item;}return null;}
 @Override public void onStart(){Bundle result=new Bundle();Context c=getTargetContext();File archive=new File(c.getCacheDir(),"native-folders.zip");ArrayList<JSONObject> imported=new ArrayList<>();AtomicReference<HostService> host=new AtomicReference<>();ServiceConnection binding=new ServiceConnection(){public void onServiceConnected(ComponentName n,IBinder b){host.set(((HostService.LocalBinder)b).getService());}public void onServiceDisconnected(ComponentName n){host.set(null);}};
 try{
  byte[] png=android.util.Base64.decode("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6ZQAAAABJRU5ErkJggg==",0);String original="Dự án ảnh "+System.currentTimeMillis();byte[] expected="Tên và nội dung nguyên bản".getBytes("UTF-8");
  try(ZipOutputStream zip=new ZipOutputStream(new FileOutputStream(archive))){for(String entry:new String[]{original+"/",original+"/con/",original+"/con/rỗng/",original+"/thư mục rỗng/",original+"/con/Tên gốc.txt",original+"/Tên gốc.txt",original+"/zero.bin",original+"/con/Hình gốc.png"}){zip.putNextEntry(new ZipEntry(entry));if(entry.endsWith(".txt"))zip.write(expected);if(entry.endsWith(".png"))zip.write(png);zip.closeEntry();}}
  for(int round=0;round<2;round++){
   FolderReceive sink=new FolderReceive(c);JSONObject receipt;
   try{FolderPackage.Result unpacked=FolderPackage.extract(archive,sink,new TransferClient.Cancellation(),(bytes,name)->{});check(unpacked.files==4,"Folder file count changed");receipt=sink.commit(archive.length(),unpacked);imported.add(receipt);}finally{sink.rollback();}
   check(receipt.getString("name").equals(round==0?original:original+" (1)"),"Root name/collision policy changed");check(FolderReceive.stillSaved(c,receipt),"Folder receipt cannot verify its files and empty directories");
   ByteArrayOutputStream raw=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(receipt.getString("inventory"))){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)raw.write(b,0,n);}JSONArray files=new JSONObject(raw.toString("UTF-8")).getJSONArray("files");check(files.length()==4,"Missing folder files");
   for(int i=0;i<files.length();i++){Uri uri=Uri.parse(files.getJSONObject(i).getString("uri"));String name,relative;try(Cursor cursor=c.getContentResolver().query(uri,new String[]{MediaStore.MediaColumns.DISPLAY_NAME,MediaStore.MediaColumns.RELATIVE_PATH,MediaStore.MediaColumns.IS_PENDING},null,null,null)){check(cursor!=null&&cursor.moveToFirst(),"Missing MediaStore row");name=cursor.getString(0);relative=cursor.getString(1);check(cursor.getInt(2)==0,"Completed folder file is still pending");}check(name.equals("Tên gốc.txt")||name.equals("zero.bin")||name.equals("Hình gốc.png"),"Individual filename was renamed");check(relative.startsWith(receipt.getString("path")+"/"),"File escaped original folder");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getContentResolver().openInputStream(uri)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}check(Arrays.equals(out.toByteArray(),name.endsWith(".txt")?expected:name.endsWith(".png")?png:new byte[0]),"Folder file bytes changed");}
  }
  stage("folders_names_empty_dirs_and_no_overwrite_verified");
  c.startForegroundService(new Intent(c,HostService.class));check(c.bindService(new Intent(c,HostService.class),binding,Context.BIND_AUTO_CREATE),"Host binding failed");await(()->host.get()!=null&&host.get().isReady(),"Native host did not start");String origin=host.get().getUrl();
  JSONObject share=TransferClient.send(origin,Arrays.asList(new TransferClient.Source(original+".zip",FolderPackage.MIME,archive.length(),()->new FileInputStream(archive))),(index,bytes,total)->{},new TransferClient.Cancellation());String code=share.getString("code");String session=host.get().transfers().beginCodeReceive(origin,share,null);
  c.startForegroundService(new Intent(c,ReceiveService.class).putExtra("origin",origin).putExtra("code",code).putExtra("sessionId",session));await(()->history(c,code)!=null,"Native ReceiveService did not import marked folder");JSONObject saved=history(c,code);check(saved.getString("path").equals("Download/FlowDrop/"+original+" (2)"),"Native folder was saved as ZIP or routed incorrectly");
  JSONObject receipt=new JSONObject(c.getSharedPreferences("received-files",0).getString(origin+code+"/"+share.getJSONArray("files").getJSONObject(0).getString("id"),"{}"));imported.add(receipt);check(FolderReceive.stillSaved(c,receipt),"Native folder files are incomplete");
  await(()->{JSONArray sessions=host.get().sessions();for(int i=0;i<sessions.length();i++){JSONObject s=sessions.getJSONObject(i);if(session.equals(s.optString("id")))return "completed".equals(s.optString("state"));}return false;},"Folder transfer completed before or without native import confirmation");
  result.putString("result",new JSONObject().put("passed",true).put("sdk",Build.VERSION.SDK_INT).put("originalFolderName",true).put("nestedDirectories",true).put("emptyDirectories",true).put("exactOriginalFilenamesAndBytes",true).put("folderCollisionKeepsFilesUnchanged",true).put("nativeReceiveService",true).put("completionAfterImport",true).toString());finish(Activity.RESULT_OK,result);
 }catch(Throwable error){result.putString("failure",android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}finally{archive.delete();try{c.unbindService(binding);}catch(Exception ignored){}}}
}
